import{_ as a,o as t,c as i,a3 as n}from"./chunks/framework.C9jfXJBR.js";const g=JSON.parse(`{"title":"Guides","description":"Explore BlendSDK's comprehensive guides to level up your development skills. Start from the basics and advance to sophisticated application stacks!","frontmatter":{"title":"Guides","description":"Explore BlendSDK's comprehensive guides to level up your development skills. Start from the basics and advance to sophisticated application stacks!"},"headers":[],"relativePath":"guides/index.md","filePath":"guides/index.md","lastUpdated":1788344325000}`),r={name:"guides/index.md"};function o(s,e,l,d,u,c){return t(),i("div",null,[...e[0]||(e[0]=[n('<p>Welcome to the BlendSDK Guides section! Whether you are just beginning your journey or are an experienced developer looking to delve into advanced topics, our guides offer step-by-step instructions and best practices. Explore our curated paths to find the right starting point for your needs.</p><h2 id="featured-blendscript" tabindex="-1">Featured: BlendScript <a class="header-anchor" href="#featured-blendscript" aria-label="Permalink to &quot;Featured: BlendScript&quot;">​</a></h2><h3 id="blendscript-course" tabindex="-1"><a href="/blendsdk/guides/blendscript-v1.html">BlendScript Course</a> <a class="header-anchor" href="#blendscript-course" aria-label="Permalink to &quot;[BlendScript Course](/guides/blendscript-v1)&quot;">​</a></h3><p>Learn BlendScript as a formula author, then integrate it into an external TypeScript application. The first part is written for people familiar with spreadsheet formulas; no programming knowledge is required.</p><ul><li><strong>Difficulty:</strong> Beginner to Intermediate</li></ul><h2 id="getting-started-path" tabindex="-1">Getting Started Path <a class="header-anchor" href="#getting-started-path" aria-label="Permalink to &quot;Getting Started Path&quot;">​</a></h2><h3 id="standard-library" tabindex="-1"><a href="/blendsdk/guides/stdlib.html">Standard Library</a> <a class="header-anchor" href="#standard-library" aria-label="Permalink to &quot;[Standard Library](/guides/stdlib)&quot;">​</a></h3><p>Discover zero-dependency utility functions, type guards, and string formatting with the BlendSDK standard library. Perfect as a foundational primer before diving into more complex projects.</p><ul><li><strong>Difficulty:</strong> Beginner</li></ul><h3 id="building-rest-apis" tabindex="-1"><a href="/blendsdk/guides/rest-api.html">Building REST APIs</a> <a class="header-anchor" href="#building-rest-apis" aria-label="Permalink to &quot;[Building REST APIs](/guides/rest-api)&quot;">​</a></h3><p>Learn to build a production-ready REST API using BlendSDK, equipped with structured logging and best practices to streamline your backend development.</p><ul><li><strong>Difficulty:</strong> Intermediate</li></ul><h3 id="database-operations" tabindex="-1"><a href="/blendsdk/guides/database.html">Database Operations</a> <a class="header-anchor" href="#database-operations" aria-label="Permalink to &quot;[Database Operations](/guides/database)&quot;">​</a></h3><p>Master type-safe SQL building and CRUD operations while integrating PostgreSQL into your BlendSDK applications for powerful data management.</p><ul><li><strong>Difficulty:</strong> Intermediate</li></ul><h3 id="postgresql-database-migrations" tabindex="-1"><a href="/blendsdk/guides/database-migrations.html">PostgreSQL Database Migrations</a> <a class="header-anchor" href="#postgresql-database-migrations" aria-label="Permalink to &quot;[PostgreSQL Database Migrations](/guides/database-migrations)&quot;">​</a></h3><p>Change a <code>DatabaseSchema</code> once, generate reviewable SQL from the committed snapshot, and apply the same immutable history in every environment.</p><ul><li><strong>Difficulty:</strong> Intermediate</li></ul><h2 id="full-stack-path" tabindex="-1">Full-Stack Path <a class="header-anchor" href="#full-stack-path" aria-label="Permalink to &quot;Full-Stack Path&quot;">​</a></h2><h3 id="building-rest-apis-1" tabindex="-1"><a href="/blendsdk/guides/rest-api.html">Building REST APIs</a> <a class="header-anchor" href="#building-rest-apis-1" aria-label="Permalink to &quot;[Building REST APIs](/guides/rest-api)&quot;">​</a></h3><p>Build robust REST APIs that serve as the backbone of your full-stack applications. This guide focuses on scalability and seamless integration.</p><ul><li><strong>Difficulty:</strong> Intermediate</li></ul><h3 id="database-operations-1" tabindex="-1"><a href="/blendsdk/guides/database.html">Database Operations</a> <a class="header-anchor" href="#database-operations-1" aria-label="Permalink to &quot;[Database Operations](/guides/database)&quot;">​</a></h3><p>Enhance your full-stack projects with efficient database interaction through BlendSDK&#39;s tools for smooth CRUD operations and seamless PostgreSQL integration.</p><ul><li><strong>Difficulty:</strong> Intermediate</li></ul><h3 id="caching-pub-sub" tabindex="-1"><a href="/blendsdk/guides/caching.html">Caching &amp; Pub/Sub</a> <a class="header-anchor" href="#caching-pub-sub" aria-label="Permalink to &quot;[Caching &amp; Pub/Sub](/guides/caching)&quot;">​</a></h3><p>Implement caching and pub/sub patterns using Redis and in-memory strategies, optimized for performance and reliability in BlendSDK applications.</p><ul><li><strong>Difficulty:</strong> Intermediate</li></ul><h3 id="authentication" tabindex="-1"><a href="/blendsdk/guides/authentication.html">Authentication</a> <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;[Authentication](/guides/authentication)&quot;">​</a></h3><p>Ensure secure user authentication using JWT, OAuth2, and OIDC discovery, while managing multi-tenant environments with BlendSDK&#39;s robust security features.</p><ul><li><strong>Difficulty:</strong> Intermediate</li></ul><h3 id="sending-email" tabindex="-1"><a href="/blendsdk/guides/email.html">Sending Email</a> <a class="header-anchor" href="#sending-email" aria-label="Permalink to &quot;[Sending Email](/guides/email)&quot;">​</a></h3><p>Integrate domain-specific SMTP email capabilities including template support and comprehensive testing patterns with BlendSDK&#39;s seamless email solutions.</p><ul><li><strong>Difficulty:</strong> Intermediate</li></ul><h3 id="internationalization" tabindex="-1"><a href="/blendsdk/guides/i18n.html">Internationalization</a> <a class="header-anchor" href="#internationalization" aria-label="Permalink to &quot;[Internationalization](/guides/i18n)&quot;">​</a></h3><p>Build global-ready applications with multi-language support through translation catalogs, locale resolution, and custom sources integration.</p><ul><li><strong>Difficulty:</strong> Intermediate</li></ul><h2 id="advanced-tooling-path" tabindex="-1">Advanced/Tooling Path <a class="header-anchor" href="#advanced-tooling-path" aria-label="Permalink to &quot;Advanced/Tooling Path&quot;">​</a></h2><h3 id="code-generation" tabindex="-1"><a href="/blendsdk/guides/code-generation.html">Code Generation</a> <a class="header-anchor" href="#code-generation" aria-label="Permalink to &quot;[Code Generation](/guides/code-generation)&quot;">​</a></h3><p>Efficiently generate TypeScript types, Zod schemas, and OpenAPI specs from your database schema to streamline your development workflow.</p><ul><li><strong>Difficulty:</strong> Advanced</li></ul><h3 id="production-migration-runbook" tabindex="-1"><a href="/blendsdk/guides/database-migrations-production.html">Production Migration Runbook</a> <a class="header-anchor" href="#production-migration-runbook" aria-label="Permalink to &quot;[Production Migration Runbook](/guides/database-migrations-production)&quot;">​</a></h3><p>Deploy committed PostgreSQL migrations through one guarded job with preflight, verification, and forward-recovery procedures.</p><ul><li><strong>Difficulty:</strong> Advanced</li></ul><h3 id="structured-logging" tabindex="-1"><a href="/blendsdk/guides/logging.html">Structured Logging</a> <a class="header-anchor" href="#structured-logging" aria-label="Permalink to &quot;[Structured Logging](/guides/logging)&quot;">​</a></h3><p>Employ production-ready structured logging using Pino, designed for deep integration with BlendSDK web applications for superior logging capabilities.</p><ul><li><strong>Difficulty:</strong> Advanced</li></ul><h3 id="react-integration" tabindex="-1"><a href="/blendsdk/guides/react.html">React Integration</a> <a class="header-anchor" href="#react-integration" aria-label="Permalink to &quot;[React Integration](/guides/react)&quot;">​</a></h3><p>Leverage BlendSDK&#39;s React utilities like custom hooks for authentication, i18n, and APIs to build cohesive full-stack applications.</p><ul><li><strong>Difficulty:</strong> Advanced</li></ul><h3 id="cli-tools" tabindex="-1"><a href="/blendsdk/guides/cmdline.html">CLI Tools</a> <a class="header-anchor" href="#cli-tools" aria-label="Permalink to &quot;[CLI Tools](/guides/cmdline)&quot;">​</a></h3><p>Develop sophisticated command-line tools with BlendSDK&#39;s features for argument parsing and dynamic help generation.</p><ul><li><strong>Difficulty:</strong> Advanced</li></ul><h2 id="suggested-learning-order" tabindex="-1">Suggested Learning Order <a class="header-anchor" href="#suggested-learning-order" aria-label="Permalink to &quot;Suggested Learning Order&quot;">​</a></h2><p>For those new to the BlendSDK, we recommend starting with:</p><ol><li><a href="/blendsdk/guides/blendscript-v1.html">BlendScript Course</a> for formula-based business rules</li><li><a href="/blendsdk/guides/stdlib.html">Standard Library</a> for general TypeScript utilities</li><li><a href="/blendsdk/guides/rest-api.html">Building REST APIs</a> for server applications</li><li><a href="/blendsdk/guides/database.html">Database Operations</a> for data access</li></ol><p>For further learning, follow the paths designed above that align with your skill level and project needs.</p><div class="tip custom-block"><p class="custom-block-title">Reference API Documentation</p><p>For detailed API references and deeper dives into specific functionalities, refer to the <a href="/blendsdk/packages/webafx.html">Package Documentation</a> covering all BlendSDK components.</p></div><p>Gain comprehensive knowledge and elevate your development skills with our structured learning paths. Happy coding with BlendSDK!</p>',59)])])}const p=a(r,[["render",o]]);export{g as __pageData,p as default};
